Given a string s consisting of the characters 0, 1 and 2, find the length of the smallest substring of string s that contains all the three characters 0, 1 and 2. If no such substring exists, then return -1.Examples:Input: s = "01212"Output: 3Explanation: The substring 012 is the smallest substring that contains the characters 0, 1 and 2.Input: s = "12121"Output: -1Explanation:  As the character 0 is not present in the string s, therefore no substring containing all the three characters 0, 1 and 2 exists. Hence, the answer is -1 in this case.Try It YourselfTable of ContentUsing Index Tracking - O(n) Time and O(1) SpaceUsing a sliding window - O(n) Time and O(1) SpaceUsing Index Tracking - O(n) Time and O(1) SpaceThe idea is to keep track of the last seen indices of '0', '1', and '2' while iterating through the string. Once all three characters are found, compute the substring length as the difference between the maximum and minimum of the three indices. Update the minimum length found and print the result.
            C++

    #include <algorithm>
#include <climits>
#include <iostream>
#include <string>

using namespace std;

int smallestSubstring(string &s)
{
    int res = INT_MAX;

    // To check 0, 1 and 2
    bool zero = false, one = false, two = false;

    // To store indexes of 0, 1 and 2
    int zeroindex, oneindex, twoindex;

    for (int i = 0; i < s.length(); i++)
    {
        if (s[i] == '0')
        {
            zero = true;
            zeroindex = i;
        }
        else if (s[i] == '1')
        {
            one = true;
            oneindex = i;
        }
        else if (s[i] == '2')
        {
            two = true;
            twoindex = i;
        }

        // Calculating length
        if (zero and one and two)
            res = min(res, max({zeroindex, oneindex, twoindex}) - min({zeroindex, oneindex, twoindex}));
    }

    // In case if there is no substring that contains 0,1 and 2
    if (res == INT_MAX)
        return -1;
    return res + 1;
}

int main()
{
    string s = "01212";
    cout << smallestSubstring(s);
    return 0;
}


